#[inductive(initialize)]
fn initialize_inductive(post: Self, rc_width: int, init_t: T) {
    broadcast use group_multiset_axioms;
    assert forall |r: int| imply(
        0 <= r < rc_width,
        post.ref_counts.index(r) ==
            post.shared_pending.count(r) as int +
                Self::filter_r(post.shared_guard, r).len() as int,
    ) by {
        if 0 <= r < rc_width {
        assert(post.ref_counts == IMap::new(
            |i: int| 0 <= i < rc_width,
            |i: int| 0int,
        ));
        vstd::iset::lemma_iset_mk_map_domain(
            ISet::new(|i: int| 0 <= i < rc_width),
            |i: int| 0int,
        );
        assert(post.ref_counts.dom().contains(r));
        vstd::iset::lemma_iset_new(|i: int| 0 <= i < rc_width, r);
        vstd::iset::lemma_iset_mk_map_index(
            ISet::new(|i: int| 0 <= i < rc_width),
            |i: int| 0int,
            r,
        );
        assert(post.ref_counts.index(r) == 0);
        assert(post.shared_pending.count(r) == 0);
        let filtered = Self::filter_r(post.shared_guard, r);
        assert forall |x: (int, T)|
            filtered.count(x) == Multiset::<(int, T)>::empty().count(x) by {
            assert(filtered.count(x) == 0);
            assert(Multiset::<(int, T)>::empty().count(x) == 0);
        };
        assert(filtered =~= Multiset::<(int, T)>::empty());
        lemma_multiset_empty_len(filtered);
        assert(filtered.len() == 0);
        }
    };
}
